const Q=(id,prompt,options,answer,why,concept)=>({id:'bonding.'+id,prompt,options,answer,why,concept:'bonding.'+concept});
const N=(id,prompt,answer,why,concept,unit='atoms')=>({...Q(id,prompt,[],answer,why,concept),type:'number',tolerance:0,unit});
const C=(title,text,scene)=>({title,text,scene});
export const structureLessons=[
{id:'science.chemistry.bonding.states',title:'States, changes & state symbols',short:'Same particles, new arrangement',refs:['2.2.1','2.2.2'],minutes:25,widget:'states-lab',prerequisites:['science.chemistry.bonding.chemical-bonds','equations'],higherQuestions:['bonding.p-stateht','bonding.c-stateht'],big:'Use melting and boiling data to predict a substance’s state. Changing state changes the arrangement of particles, not the identity of its atoms.',learn:[
C('Read the two boundaries.','At a specified pressure, below its melting point a pure substance is solid; between its melting and boiling points it is liquid; above its boiling point it is gas. At a transition temperature, two states can coexist, so temperature alone does not determine their proportions. A liquid’s particles remain close together but can move past each other; gas particles are widely separated.','phase:liquid'),
C('Track energy and forces.','Melting is solid to liquid; freezing is the reverse. Boiling is liquid to gas; condensation is the reverse. Heating supplies energy to overcome attractions; cooling removes energy as attractions bring particles together. Stronger attractions generally need more energy to overcome. In a molecular substance, these are forces between molecules; in an ionic or giant covalent structure, stronger bonding is involved. Atoms themselves do not have bulk properties such as being a solid or melting.','phase:solid'),
C('Put state symbols into equations.','Use (s) for solid, (l) for liquid and (g) for gas. Use (aq) when a substance is dissolved in water: NaCl(aq) is salt solution, while NaCl(l) is molten salt. For neutralisation: HCl(aq) + NaOH(aq) → NaCl(aq) + H₂O(l). The water is the liquid solvent; the other named substances are dissolved in it.','phase:gas'),
{...C('Higher: question the particle model.','Solid-sphere models can suggest particles are solid, inelastic balls with no forces between them. Real particles interact and are not simply solid balls. Without representing forces, the model cannot explain the energy needed to separate particles during a change of state. It is useful for arrangement, but insufficient as a full explanation of state changes.','phase:liquid'),higher:true}],practice:[
Q('p-state1','A substance melts at −20 °C and boils at 80 °C. At 25 °C it is…',['Solid','Liquid','Gas'],1,'25 lies above −20 and below 80.','states'),
Q('p-state2','Which symbol describes sodium chloride dissolved in water?',['(l)','(aq)','(g)'],1,'Aqueous means dissolved in water, not molten.','state-symbols'),
Q('p-state3','Condensation changes…',['Gas to liquid','Liquid to gas','Solid to liquid'],0,'Cooling a gas can bring particles closer as attractions act.','phase-energy'),
Q('p-stateht','What is missing from a particle model with solid spheres and no interactions?',['Forces needed to explain energy during state changes','The names of all laboratory equipment','A different element in each state'],0,'The no-force model cannot explain the energy needed to overcome attractions.','state-models')],check:[
Q('c-state1','A pure substance melts at 15 °C and boils at 95 °C. At 10 °C, its state is…',['Solid','Liquid','Gas'],0,'10 °C is below the melting point.','states'),
Q('c-state2','The same substance (melting 15 °C, boiling 95 °C) is at 110 °C. State?',['Solid','Liquid','Gas'],2,'110 °C is above the boiling point.','states'),
Q('c-state3','Which is correctly labelled for a salt dissolved in water?',['NaCl(aq)','NaCl(l)','NaCl(g)'],0,'(aq) identifies an aqueous solution.','state-symbols'),
Q('c-state4','What happens when a molecular liquid boils?',['Energy is supplied to overcome attractions between molecules','Each atom melts into a liquid atom','Every molecule must split into separate atoms'],0,'Molecules separate; their atoms need not change identity or bonding.','phase-energy'),
Q('c-state5','At the melting point of a pure substance, what can be present?',['Both solid and liquid','Only gas under all conditions','Only solid under all conditions'],0,'During melting, solid and liquid can coexist at the melting point.','states'),
Q('c-stateht','Why is a model of solid spheres with no forces limited for explaining boiling?',['It cannot account for energy needed to overcome particle attractions','It predicts every substance has different atoms after boiling','It includes every interaction in full detail'],0,'The missing attractions are essential to an explanation of state change.','state-models')],skills:['WS1.2','MS5b']},
{id:'science.chemistry.bonding.molecular-properties',title:'Small molecules & intermolecular forces',short:'Strong inside, weaker between',refs:['2.2.4'],minutes:20,widget:'molecular-lab',prerequisites:['science.chemistry.bonding.covalent-molecules','science.chemistry.bonding.states'],big:'Boiling separates molecules by overcoming intermolecular forces. It does not normally break the strong covalent bonds within each molecule.',learn:[
C('Two different attractions.','Inside a water molecule, O–H covalent bonds hold the atoms together. Between water molecules, intermolecular forces attract one molecule to another. These are weaker than covalent bonds. Boiling water separates intact H₂O molecules; it does not produce hydrogen and oxygen gases. The model exaggerates separation and shows only a few molecules.','molecular:close'),
C('Explain low boiling points and trends.','Small molecular substances often have relatively low melting and boiling points because comparatively little energy is needed to overcome forces between their molecules. For a related series of molecules, intermolecular forces tend to become stronger as molecules become larger, raising boiling points. Compare supplied data: size alone does not determine boiling points across all unrelated substances.','molecular:apart'),
C('Look for a mobile charge carrier.','Small molecules have no overall electric charge. A pure molecular substance generally lacks mobile ions or delocalised electrons, so it does not conduct electricity. Dissolving some molecular substances can produce ions: hydrogen chloride solution is a later example. Do not use “contains electrons” as proof of conduction; charge carriers must be able to move through the material.','molecular:close')],practice:[
Q('p-molprop1','What is overcome when liquid oxygen boils?',['Forces between O₂ molecules','The O=O covalent bonds','The oxygen nuclei'],0,'The O₂ molecules separate while retaining their covalent bonds.','intermolecular'),
Q('p-molprop2','Why do larger molecules in a related series often boil at higher temperatures?',['Stronger intermolecular forces need more energy to overcome','Their atoms have no electrons','All bonds become ionic'],0,'The trend concerns forces between molecules, not a change of bond type.','molecular-trends'),
Q('p-molprop3','Why does pure methane not conduct electricity?',['It lacks mobile charged particles','It contains no electrons at all','Its molecules have an overall positive charge'],0,'Neutral molecules do not carry a current; electrons are not delocalised.','molecular-conduction')],check:[
Q('c-molprop1','A sample of pure water becomes steam. Which particles are present in the steam?',['H₂O molecules','Only separate H and O atoms','Only H₂ and O₂ molecules'],0,'Boiling retains the covalent bonds inside water molecules.','intermolecular'),
Q('c-molprop2','Why is a molecular boiling point often much lower than a giant covalent melting point?',['Weaker intermolecular forces are overcome rather than a network of strong covalent bonds','Molecular substances contain no forces','Atoms in molecules have no mass'],0,'Different interactions require different amounts of energy to overcome.','intermolecular'),
Q('c-molprop3','Related hydrocarbons have boiling points −162, −89 and −42 °C as molecule size increases. Predict the next trend.',['A higher boiling point','A lower boiling point','An identical boiling point is guaranteed'],0,'In this related series, larger molecules have stronger intermolecular forces.','molecular-trends'),
Q('c-molprop4','Which would help a substance conduct electricity?',['Charged particles able to move through it','Neutral molecules merely moving faster','Electrons permanently bound to one atom'],0,'Conduction requires mobile charge carriers.','molecular-conduction'),
Q('c-molprop5','Which description is correct?',['Covalent bonds are inside molecules; intermolecular forces act between molecules','Intermolecular forces hold protons together in nuclei','Boiling always breaks all covalent bonds'],0,'Distinguish within a molecule from between separate molecules.','intermolecular')],skills:['WS1.2']},
{id:'science.chemistry.bonding.polymers',title:'Polymers & repeating units',short:'One pattern, a very long molecule',refs:['2.1.4','2.2.5'],minutes:25,widget:'polymer-lab',prerequisites:['science.chemistry.bonding.molecular-properties'],big:'A polymer is a very large molecule with strong covalent bonds along its chain. A repeating-unit diagram shows a pattern continuing many times.',learn:[
C('Recognise a long molecule.','A polymer contains many repeating units joined into a very large molecule. There are strong covalent bonds between atoms along each chain. Separate polymer chains attract each other through intermolecular forces. A polymer chain is a molecule; it is not automatically a giant covalent network extending in every direction.','structure:polymer'),
C('Read the brackets and n.','For poly(ethene), the repeating unit is –CH₂–CH₂–. Draw two carbons joined by a single bond, attach two hydrogens to each carbon and show single bonds extending through brackets at both ends. The n outside the brackets means the unit repeats a large number of times. It does not mean the diagram contains only n atoms. Hydrogen atoms are omitted in the skeletal 3D view; the labelled 2D activity includes them.','structure:polymer'),
C('Connect chains to properties.','Compared with small molecules, large polymer molecules have relatively strong intermolecular attractions across their chains. Many familiar polymers are solids at room temperature. Strong covalent bonds remain within each molecule. Softening can allow chains to move without breaking every covalent bond; heating a polymer strongly can also cause chemical decomposition. This lesson covers structure and properties; polymerisation reactions come later.','structure:polymer')],practice:[
Q('p-poly1','What does n outside a repeating-unit bracket mean?',['The unit repeats many times','There are exactly n hydrogen atoms','Every bond is a double bond'],0,'n counts repeats of the whole bracketed unit.','polymer-repeat'),
Q('p-poly2','What holds atoms together along a poly(ethene) chain?',['Strong covalent bonds','Only intermolecular forces','Ionic bonds between Na⁺ and Cl⁻'],0,'Intermolecular forces act between chains, while covalent bonds connect atoms within a chain.','polymer-properties'),
N('p-poly3','The unit –CH₂–CH₂– repeats 5 times. Ignoring end groups, how many carbon atoms are represented?',10,'Each unit has two carbons: 2 × 5 = 10.','polymer-repeat')],check:[
Q('c-poly1','Which description identifies a polymer?',['Very long molecules containing repeating units','A collection of individual unbonded atoms only','A lattice of oppositely charged ions'],0,'Repeating units join to make large molecules.','polymer-repeat'),
Q('c-poly2','A correct poly(ethene) repeat diagram has…',['Single bonds with bonds continuing through both brackets','A double C=C bond in every repeat','No bonds between repeats'],0,'The chain continues beyond both bracket edges.','polymer-repeat'),
N('c-poly3','For 7 repeats of –CH₂–CH₂–, ignoring end groups, how many H atoms are represented?',28,'Each unit has four H atoms: 4 × 7 = 28.','polymer-repeat'),
Q('c-poly4','Why are many polymers solids at room temperature?',['Their large molecules have relatively strong attractions between chains','They are made of ionic salt molecules','They contain no forces between chains'],0,'The relatively strong intermolecular attractions restrain chain movement.','polymer-properties'),
Q('c-poly5','Which pair distinguishes a chain from forces between chains?',['Covalent bonds within; intermolecular forces between','Intermolecular forces within; nuclei between','No bonds within; covalent bonds only between every chain'],0,'Keep within-molecule bonds separate from between-molecule attractions.','polymer-properties')],skills:['WS1.2','MS5b','MS1c']},
{id:'science.chemistry.bonding.giant-covalent',title:'Giant covalent structures',short:'A network beyond the edge',refs:['2.1.4','2.2.6'],minutes:20,widget:'network-lab',prerequisites:['science.chemistry.bonding.polymers','science.chemistry.bonding.covalent-molecules'],big:'In a giant covalent structure, strong covalent bonds link atoms throughout a network. Melting requires overcoming many strong bonds, so melting points are very high.',learn:[
C('Spot a continuous network.','Small molecular diagrams show separate groups of atoms. Polymer diagrams show long but separate molecules. A giant covalent diagram shows a network continuing beyond the edges of the sample. Diamond, graphite and silicon dioxide are giant covalent substances. Carbon structures differ in their detailed bonding and properties; these differences are explored next.','structure:network'),
C('A line represents a bond.','In silicon dioxide, each silicon is covalently bonded to four oxygen atoms and each oxygen links two silicon atoms. The overall ratio is one Si to two O: SiO₂ is a ratio in a network, not the formula of a separate three-atom molecule. A flat fragment can show connections using lines for single bonds, but cannot show the whole three-dimensional arrangement. At the displayed edges, bonds continue into the rest of the structure.','structure:network'),
C('Explain the energy requirement.','Many strong covalent bonds must be overcome to melt a giant covalent structure, requiring a great deal of energy. These substances are solids with very high melting points. Do not apply the small-molecule explanation of weak forces between separate molecules to diamond or silica. Electrical conductivity depends on the detailed structure: graphite has delocalised electrons; diamond and silica do not.','structure:network')],practice:[
Q('p-network1','Which structural evidence suggests a giant covalent substance?',['A continuous covalently bonded network','Only separate two-atom molecules','Positive and negative ions alternating'],0,'A network links atoms throughout the structure.','giant-covalent'),
Q('p-network2','Why does silica have a very high melting point?',['Many strong covalent bonds must be overcome','Only weak forces between SiO₂ molecules must be overcome','Its atoms are individually hot solids'],0,'Silica is a giant network, not discrete SiO₂ molecules.','giant-properties'),
Q('p-network3','What is hidden by a flat silica fragment diagram?',['The full three-dimensional arrangement','The fact that Si and O are different elements','Every visible bond'],0,'2D is useful for connectivity but hides depth and omits the rest of the network.','network-models')],check:[
Q('c-network1','Which substance has a giant covalent structure?',['Silicon dioxide','Hydrogen chloride','Methane'],0,'Silica is an extended network of covalently bonded atoms.','giant-covalent'),
Q('c-network2','In a giant covalent structure, melting mainly requires overcoming…',['Strong covalent bonds throughout a network','Only weak attractions between small molecules','Attraction between positive and negative ions'],0,'Many strong covalent bonds link its atoms.','giant-properties'),
Q('c-network3','What does SiO₂ describe in solid silica?',['The overall Si:O ratio of 1:2','Separate molecules containing exactly three atoms','A metal with two delocalised electrons per atom'],0,'The formula gives a network ratio, not discrete molecules.','giant-covalent'),
Q('c-network4','Why draw bonds continuing past the edge of a network fragment?',['The structure extends beyond the displayed sample','The bonds are physically cut in every real crystal','The substance consists only of the displayed atoms'],0,'The fragment represents part of a much larger structure.','network-models'),
Q('c-network5','Which distinction is correct?',['Polymer chains are large molecules; a giant covalent network extends throughout the structure','Every polymer is a giant ionic lattice','All covalent substances are small molecules'],0,'Bond type alone does not determine whether the structure is molecular or giant.','giant-covalent')],skills:['WS1.2','MS5b']}
];
